import assert from 'node:assert/strict';
import { createHash, createPublicKey, verify } from 'node:crypto';
import { readFile, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';
const directory = resolve(import.meta.dirname, '..');
const receipts = [];
for (const name of ['baseline', 'candidate']) {
  const raw = await readFile(resolve(directory, `${name}-multi-wallet.json`));
  const campaign = JSON.parse(raw);
  const keys = new Map();
  for (const wallet of campaign.wallets) {
    const bytes = Buffer.from(wallet.publicKeyHex, 'hex');
    assert.equal(bytes.length, 1952);
    assert.deepEqual(createHash('sha256').update(bytes).digest(), Buffer.from(wallet.key.public_key_digest));
    const key = createPublicKey({key:Buffer.concat([Buffer.from('308207b2300b0609608648016503040312038207a100','hex'),bytes]),format:'der',type:'spki'});
    assert.equal(key.asymmetricKeyType,'ml-dsa-65');
    keys.set(wallet.index,key);
  }
  const results = [];
  const identities = new Set();
  for (const row of campaign.requests) {
    if (row.state !== 'succeeded') continue;
    assert.equal(row.verified,true);
    const key = keys.get(row.wallet);
    assert.ok(key);
    const operation = Buffer.from(row.operation).toString('hex');
    assert.ok(!identities.has(operation));
    identities.add(operation);
    const message = Buffer.from(row.messageHex,'hex');
    const signature = Buffer.from(row.signatureHex,'hex');
    assert.equal(message.length,32);
    assert.equal(signature.length,3309);
    assert.equal(verify(null,message,key,signature),true);
    const changedMessage = Buffer.from(message);
    changedMessage[0] ^= 1;
    assert.equal(verify(null,changedMessage,key,signature),false);
    const changedSignature = Buffer.from(signature);
    changedSignature[0] ^= 1;
    assert.equal(verify(null,message,key,changedSignature),false);
    results.push({wallet:row.wallet,operation,verified:true,alteredMessageRejected:true,alteredSignatureRejected:true});
  }
  assert.equal(results.length,name==='baseline'?19:25);
  receipts.push({campaign:name,clientSha256:createHash('sha256').update(raw).digest('hex'),node:process.version,openssl:process.versions.openssl,context:'Empty per retained runner',results});
}
await writeFile(resolve(import.meta.dirname,'multi-signature-verification.json'),JSON.stringify(receipts,null,2)+'\n');
console.log(JSON.stringify(receipts.map(row=>({campaign:row.campaign,verified:row.results.length,negativeControls:row.results.length*2}))));
